mapper.sql:
AND problem_id IN (
	SELECT problem_id
	FROM voj_problems
	WHERE problem_status = 'PUBLISHED'
)
AND (
	uid = #{viewerUid}
	OR NOT EXISTS (
		SELECT 1
		FROM voj_contest_submissions running_cs
		JOIN voj_contests running_c ON running_c.contest_id = running_cs.contest_id
		WHERE running_cs.submission_id = voj_submissions.submission_id
		AND running_c.contest_end_time > #{now}
	)
)

